// Code-native scientific diagrams paired with generated specimen cutouts.
const ink='#405951',teal='#528d80',copper='#c78d6b',faint='#c8d7ce';
const line=(d,color=ink,width=1.4,extra='')=>`<path d="${d}" fill="none" stroke="${color}" stroke-width="${width}" ${extra}/>`;
const label=(x,y,t,size=9,color=ink)=>`<text x="${x}" y="${y}" fill="${color}" font-family="Georgia,serif" font-size="${size}">${t}</text>`;
const dot=(x,y,r=3,color=teal,extra='')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${color}" ${extra}/>`;
export function coralArt(kind='branch',color,bleach=0){return `<image href="assets/coral-${kind}.webp" x="12" y="5" width="176" height="157" style="filter:saturate(${1-bleach/115}) brightness(${1+bleach/220})"/>`;}
export function specimenIcon(kind,color){return `<svg viewBox="0 0 200 180" aria-hidden="true"><ellipse cx="100" cy="162" rx="65" ry="5" fill="#7a8e7f" opacity=".08"/>${coralArt(kind,color)}</svg>`;}
export function bottleArt(color,formula){return `<svg viewBox="0 0 90 120" aria-hidden="true"><defs><linearGradient id="b-${formula}" x1="0" x2="1"><stop stop-color="#d2e0dc"/><stop offset=".25" stop-color="#fff"/><stop offset=".55" stop-color="#ecf2ed"/><stop offset="1" stop-color="#abc2ba"/></linearGradient></defs><ellipse cx="45" cy="111" rx="29" ry="5" fill="#465c4c" opacity=".12"/><path d="M32 23H58V42C58 49 72 51 72 60V102Q72 109 65 109H25Q18 109 18 102V60C18 51 32 49 32 42Z" fill="url(#b-${formula})" stroke="#608079" stroke-width="1.2"/><path d="M21 70Q45 66 69 70V101Q69 106 64 106H26Q21 106 21 101Z" fill="${color}" opacity=".5"/><path d="M25 58V98M29 56V94" stroke="#fff" stroke-width="2" opacity=".8"/><rect x="29" y="14" width="32" height="15" rx="3" fill="#435d58"/>${Array.from({length:7},(_,i)=>line(`M${33+i*4} 16V26`,'#78928a',.8)).join('')}<path d="M31 32H59" stroke="#94ada2"/><rect x="23" y="65" width="44" height="29" rx="1" fill="#fffdf5" stroke="#dfdeca"/>${label(27,73,'REAGENT',4.8)}<text x="45" y="85" fill="#455f56" text-anchor="middle" font-family="Georgia" font-size="9">${formula}</text>${line('M28 89H62',color,2)}${label(48,102,'SIM',4.5)}</svg>`;}
export function tankArt(g,{bleach=0,active=false,empty=false}={}){
 const n=Math.max(0,Math.min(100,bleach));
 const specimens=empty?'':[[173,266,165,130],[290,211,249,195],[485,270,153,123]].map(([x,y,w,h],i)=>`<ellipse cx="${x+w/2}" cy="${y+h-7}" rx="${w*.35}" ry="9" fill="#586b5d" opacity=".13"/><image class="tank-coral" href="assets/coral-${g.coral}.webp" x="${x}" y="${y}" width="${w}" height="${h}" preserveAspectRatio="xMidYMax meet" style="filter:saturate(${1-n/115}) brightness(${1+n/220})"/><g transform="translate(${x+w*.3} 404)"><rect width="40" height="13" rx="2" fill="#ede9d8" stroke="#a4aca0" stroke-width=".6"/>${label(8,9,'F0'+(i+1),6)}</g>`).join('');
 return `<svg class="tank-scene ${active?'incubating':''}" viewBox="0 0 820 530" role="img" aria-label="带 LED 光源、温度探头和三个珊瑚片段的虚拟培养水槽"><defs>
 <linearGradient id="bench-bg" x2="0" y2="1"><stop stop-color="#f9faf5"/><stop offset="1" stop-color="#e8eee5"/></linearGradient><linearGradient id="tank-water" x2="0" y2="1"><stop stop-color="#d4e8df" stop-opacity=".5"/><stop offset=".45" stop-color="#b5d9d0" stop-opacity=".6"/><stop offset="1" stop-color="#80b7ac" stop-opacity=".75"/></linearGradient><linearGradient id="tank-front"><stop stop-color="#fff" stop-opacity=".24"/><stop offset=".3" stop-color="#fff" stop-opacity="0"/><stop offset=".85" stop-color="#fff" stop-opacity=".03"/><stop offset="1" stop-color="#a7cabe" stop-opacity=".3"/></linearGradient><linearGradient id="metal" x2="0" y2="1"><stop stop-color="#94a6a0"/><stop offset=".4" stop-color="#ebf0e9"/><stop offset=".5" stop-color="#8a9d96"/><stop offset="1" stop-color="#536c61"/></linearGradient><linearGradient id="sand" x2="0" y2="1"><stop stop-color="#e1d8bb"/><stop offset="1" stop-color="#bcb798"/></linearGradient><pattern id="bench-grid" width="28" height="28" patternUnits="userSpaceOnUse"><path d="M28 0H0V28" fill="none" stroke="#c7d5c8" stroke-width=".5" opacity=".24"/></pattern><filter id="contact-shadow"><feGaussianBlur stdDeviation="5"/></filter></defs>
 <rect width="820" height="530" fill="url(#bench-bg)"/><rect x="44" y="35" width="735" height="440" fill="url(#bench-grid)"/>
 ${label(45,32,'CORAL MESOCOSM     /     VIRTUAL SPECIMENS',9,'#85998b')}${label(650,493,'CHAMBER 02',9,'#7a8d7e')}
 <ellipse cx="402" cy="465" rx="282" ry="16" fill="#526a57" opacity=".16" filter="url(#contact-shadow)"/>
 <path d="M125 153H632L688 192H178Z" fill="#edf4eb" fill-opacity=".65" stroke="#8da99c"/><path d="M125 153L178 192V432L125 389Z" fill="#d1e4d9" fill-opacity=".55" stroke="#91afa4"/>
 <path d="M178 213H688V432H178Z" fill="url(#tank-water)"/><path d="M126 179L178 213V432L126 389Z" fill="#9cc7ba" opacity=".5"/>
 <path d="M129 180L633 180L685 214H179Z" fill="#e2f1e8" opacity=".6"/>
 ${Array.from({length:7},(_,i)=>line(`M${192+i*62} 215q24 -3 43 0`,'#fff',.9,'opacity=".5"')).join('')}
 <path d="M180 404Q289 395 400 404T686 402V432H180Z" fill="url(#sand)"/>
 ${Array.from({length:100},(_,i)=>dot(183+(i*47)%498,405+(i*13)%24,.5+i%3*.25,i%2?'#908d70':'#f2ecd9','opacity=".45"')).join('')}
 <path d="M213 195L244 406M334 194L354 404M555 195L533 400" stroke="#fff" stroke-width="13" opacity=".035"/>
 ${specimens}
 <path d="M178 192H688V432H178Z" fill="url(#tank-front)" stroke="#759a8b" stroke-width="1.5"/><path d="M181 196H684V428H181Z" fill="none" stroke="#e9f5ed" stroke-width="1"/><path d="M188 214V388M195 217V306" stroke="white" stroke-width="2.4" opacity=".6"/>
 <path d="M125 153H632L688 192H178Z" fill="none" stroke="#6c8d7e" stroke-width="2"/><path d="M125 148H634L694 190" fill="none" stroke="#e1e9df" stroke-width="3"/>
 <path d="M653 180V344" stroke="#536f62" stroke-width="3"/><path d="M653 183V148Q653 132 676 132H710V104" fill="none" stroke="#6c7e71" stroke-width="2"/><rect x="647" y="315" width="12" height="48" rx="5" fill="#d8e2db" stroke="#6b8073"/>${Array.from({length:6},(_,i)=>line(`M650 ${323+i*5}H656`,'#879b90',.6)).join('')}
 <g transform="translate(650 64)"><rect width="109" height="59" rx="7" fill="#e1e8df" stroke="#8ea395"/><rect x="8" y="8" width="93" height="33" rx="3" fill="#f9fbef" stroke="#c2cdb7"/><text x="53" y="31" text-anchor="middle" font-family="Consolas" font-size="19" fill="#4b7663">${g.temp.toFixed(1)}°C</text>${dot(13,50,2,'#83a96e')}${label(21,52,'TEMPERATURE',5.5)}</g>
 <g fill="none" stroke="#eafaf0" opacity=".6"><circle class="bubble b1" cx="626" cy="330" r="4"/><circle class="bubble b2" cx="617" cy="282" r="2.5"/><circle class="bubble b3" cx="631" cy="241" r="3"/></g>
 <path d="M100 438H712V449H100Z" fill="url(#metal)"/><path d="M108 451H703V462H108Z" fill="#b2bdae"/><path d="M141 462V481M669 462V481" stroke="#637c6b" stroke-width="8"/>
 <path d="M219 97H569L551 117H240Z" fill="url(#metal)" stroke="#81988b"/><path d="M235 121H553" stroke="#f4e8bc" stroke-width="6"/>
 ${Array.from({length:16},(_,i)=>`<rect x="${244+i*19}" y="120" width="11" height="3" rx="1" fill="#fff9df"/>`).join('')}
 <path d="M270 95V64H511V95" fill="none" stroke="url(#metal)" stroke-width="5"/><path d="M241 126L193 218H603L549 126Z" fill="#f9edbf" opacity=".055"/>
 ${line('M87 202V425M82 202H92M82 425H92','#9eb09f',.8)}${label(54,317,'WATER',6,'#8a9a86')}
 <g transform="translate(110 83)">${label(0,0,'LED / '+g.light+'%',8,'#7f927e')}${line('M8 8H66L104 27','#a5b4a0',.8)}</g>
 </svg>`;
}
function nodesTree(x,y,s=1,offset=0){
 const pts=[[0,0],[-32,27],[32,27],[-49,54],[-15,54],[15,54],[49,54]],edges=[[0,1],[0,2],[1,3],[1,4],[2,5],[2,6]];
 return `<g transform="translate(${x} ${y}) scale(${s})">${edges.map(([a,b])=>line(`M${pts[a][0]} ${pts[a][1]}L${pts[b][0]} ${pts[b][1]}`,faint,1.3)).join('')}${pts.map(([a,b],i)=>`<rect x="${a-8}" y="${b-5}" width="16" height="10" rx="2" fill="${i===offset?copper:i>2?'#c3d8c8':'#f4ecdb'}" stroke="${i>2?teal:ink}" stroke-width=".8"/>`).join('')}</g>`;
}
export function modelArt(family,view,index){
 const axes=line('M46 157H304M46 157V39',faint,1)+[0,1,2,3].map(i=>line(`M46 ${55+i*30}H304`,'#dde5db',.55,'stroke-dasharray="2 4"')).join('');
 const points=Array.from({length:18},(_,i)=>[57+i*12.6,145-i*5.2+Math.sin(i*2.5)*12]);
 const scatter=points.map(([x,y],i)=>dot(x,y,2.5,i%4===0?copper:teal,'opacity=".75"')).join('');
 const fit=line('M54 149L292 49',teal,2),curved=line('M54 145C104 150 106 76 158 94S227 54 294 42',teal,2);
 const coeff=(zeros=false)=>Array.from({length:8},(_,i)=>{const h=[66,43,82,31,64,25,48,37][i],small=zeros&&i%3!==0?0:h*.5;return `<rect x="${57+i*28}" y="${151-h}" width="8" height="${h}" fill="#d5dfd2"/><rect x="${68+i*28}" y="${151-small}" width="8" height="${small||1}" fill="${small?teal:copper}"/>${label(60+i*28,164,'β'+(i+1),7)}`;}).join('');
 const neural=(random=false)=>{const layers=[[74,[56,88,120,152]],[173,[49,76,103,130,157]],[273,[82,124]]];return layers.slice(0,2).flatMap((layer,k)=>layer[1].flatMap(y=>layers[k+1][1].map(z=>line(`M${layer[0]} ${y}L${layers[k+1][0]} ${z}`,random?'#bcba9f':'#b0c9bc',.7,random?'stroke-dasharray="2 2"':'')))).join('')+layers.flatMap(([x,ys],k)=>ys.map((y,i)=>dot(x,y,k===1?7:6,k===1?teal:'#eee7d6',`stroke="${ink}" stroke-width=".6"`))).join('')+label(145,179,random?'fixed random layer':'learned hidden layer',8);};
 let art='',formula='';
 switch(family){
 case 'ols':art=axes+scatter+fit+points.filter((_,i)=>i%3===0).map(([x,y])=>line(`M${x} ${y}V${149-(x-54)*100/238}`,copper,.8)).join('');formula='min Σ(y − ŷ)²';break;
 case 'ridge':art=axes+coeff()+line('M60 62Q165 23 281 69',copper,1.3)+label(130,43,'shrink',9);formula='RSS + λ ‖β‖²';break;
 case 'lasso':art=axes+coeff(true);formula='RSS + λ ‖β‖₁';break;
 case 'elastic':art=axes+coeff(true)+`<path d="M265 42l23 19-23 19-23-19Z" fill="none" stroke="${copper}"/><circle cx="265" cy="61" r="18" fill="none" stroke="${teal}"/>`;formula='L1 + L2 penalties';break;
 case 'huber':art=axes+line('M65 56L133 130Q172 171 211 128L282 53',teal,2)+line('M65 35Q174 245 282 35',faint,1.2,'stroke-dasharray="3 3"')+label(149,75,'δ',12);formula='quadratic → linear loss';break;
 case 'lad':art=axes+line('M66 50L177 149L288 50',teal,2)+line('M66 31Q177 260 288 31',faint,1,'stroke-dasharray="3 3"');formula='min Σ |y − ŷ|';break;
 case 'ransac':art=axes+scatter+fit+[[97,49],[193,143],[261,137]].map(([x,y])=>dot(x,y,5,'none',`stroke="${copper}" stroke-dasharray="2 2"`)).join('')+label(70,33,'consensus',9);formula='sample → inliers → refit';break;
 case 'knn':art=axes+points.map(([x,y])=>dot(x,y,2.7,teal)).join('')+`<ellipse cx="179" cy="103" rx="56" ry="41" fill="#bcd7c7" fill-opacity=".25" stroke="${teal}" stroke-dasharray="3 4"/>`+points.slice(7,12).map(([x,y])=>line(`M179 103L${x} ${y}`,copper,.8)).join('')+dot(179,103,4,copper);formula='five weighted neighbours';break;
 case 'loess':art=axes+scatter+curved+`<ellipse cx="179" cy="103" rx="52" ry="48" fill="#bad6c5" fill-opacity=".2" stroke="${teal}" stroke-dasharray="2 3"/>`+line('M141 122L216 76',copper,1.5);formula='local tricube weights';break;
 case 'tree':art=nodesTree(177,53,1.75)+label(169,40,'x ≤ t',10);formula='recursive partitions';break;
 case 'bagging':art=[70,177,284].map(x=>nodesTree(x,48,.72)).join('')+[70,177,284].map(x=>line(`M${x} 101L177 143`,faint,1)).join('')+`<rect x="145" y="138" width="64" height="25" rx="3" fill="#ead9bd" stroke="${copper}"/>`+label(158,154,'mean',10);formula='bootstrap + aggregation';break;
 case 'forest':art=[70,177,284].map((x,i)=>nodesTree(x,54,.75,i+1)).join('')+Array.from({length:12},(_,i)=>`<rect x="${48+i*23}" y="140" width="17" height="12" fill="${i%3?'#d7e4d5':copper}" opacity=".8"/>`).join('')+label(72,172,'sampled features at every split',9);formula='trees + feature sampling';break;
 case 'extra':art=[70,177,284].map((x,i)=>nodesTree(x,54,.76,i)).join('')+Array.from({length:9},(_,i)=>line(`M${57+i*29} 132V${148+(i%3)*8}`,i%2?teal:copper,1.6)).join('')+label(98,179,'random split thresholds',9);formula='randomised trees';break;
 case 'boost':art=axes+line('M55 145H100V125H143V93H190V76H237V57H291',teal,2.7)+[0,1,2,3,4].map(i=>line(`M${76+i*45} ${56+i*4}V${131-i*18}`,copper,5)).join('');formula='fit the residual, repeat';break;
 case 'adaboost':art=[70,177,284].map(x=>nodesTree(x,45,.65)).join('')+Array.from({length:14},(_,i)=>dot(53+i*19,141,2+(i%4)*1.6,i%3?teal:copper,'opacity=".65"')).join('')+line('M83 112Q172 88 270 112',copper,1.4)+label(111,178,'reweight difficult samples',9);formula='weighted median ensemble';break;
 case 'pcr':art=line('M103 154L270 119M103 154L168 39M103 154L53 63',ink,1.2)+Array.from({length:24},(_,i)=>dot(95+i*5,124-i*2+Math.sin(i*3)*20,2,teal,'opacity=".6"')).join('')+line('M83 151L260 48',copper,2)+label(266,49,'PC₁',10)+line('M172 50L239 149',faint,1,'stroke-dasharray="2 3"');formula='variance → projection → fit';break;
 case 'pls':art=Array.from({length:20},(_,i)=>`<rect x="${52+(i%4)*13}" y="${51+Math.floor(i/4)*19}" width="10" height="15" fill="${i%3?teal:copper}" opacity="${.3+(i%3)*.2}"/>`).join('')+line('M118 96H158M205 96H246',copper,1.5)+`<rect x="161" y="60" width="39" height="74" rx="3" fill="#dae4d7" stroke="${teal}"/>`+label(175,100,'t',18)+Array.from({length:5},(_,i)=>`<rect x="258" y="${51+i*19}" width="24" height="15" fill="${teal}" opacity="${.3+i*.13}"/>`).join('')+label(66,169,'X',12)+label(264,169,'y',12);formula='max covariance(Xw, y)';break;
 case 'spline':art=axes+[-1,0,1].map((v,i)=>line(`M${90+i*76} 47V157`,copper,.8,'stroke-dasharray="3 4"')).join('')+line('M55 143L89 143L165 95L241 115L295 48',teal,2.5)+label(140,177,'training knots',9);formula='Σ fⱼ(xⱼ) + penalty';break;
 case 'kernel':art=axes+Array.from({length:5},(_,i)=>`<ellipse cx="174" cy="102" rx="${22+i*22}" ry="${12+i*12}" fill="none" stroke="${teal}" stroke-width="${i===2?1.8:.7}" opacity="${1-i*.13}"/>`).join('')+points.filter((_,i)=>i%2).map(([x,y])=>dot(x,y,2.5,copper)).join('')+label(255,47,'K(x,x′)',10);formula='exp(−γ ‖x − x′‖²)';break;
 case 'svr':art=axes+`<path d="M54 131L292 31V67L54 167Z" fill="#c7dfd0" opacity=".4"/>`+scatter+fit+line('M54 131L292 31M54 167L292 67',copper,.9,'stroke-dasharray="4 3"')+points.filter((_,i)=>i%5===0).map(([x,y])=>dot(x,y,5,'none',`stroke="${ink}" stroke-width=".8"`)).join('');formula='ε-insensitive loss';break;
 case 'mlp':art=neural();formula='forward pass + backprop';break;
 case 'elm':art=neural(true);formula='random hidden / fitted output';break;
 case 'rbfnet':art=axes+[90,177,261].map((c,i)=>line(`M${c-43} 151Q${c-24} 149 ${c-15} 92Q${c} 26 ${c+15} 92Q${c+24} 149 ${c+43} 151`,i===1?teal:copper,1.4)).join('')+[90,177,261].map(c=>dot(c,151,3,ink)).join('');formula='k-means centres + Gaussian bases';break;
 case 'omp':art=axes+Array.from({length:9},(_,i)=>`<rect x="${58+i*26}" y="${149-[47,22,75,30,60,24,82,40,28][i]}" width="12" height="${[47,22,75,30,60,24,82,40,28][i]}" fill="${[0,2,6].includes(i)?teal:'#dce3d7'}"/>`).join('')+line('M72 58L116 43L221 30',copper,1.2)+label(239,35,'residual',9);formula='select → orthogonal refit';break;
 default:throw Error('Missing illustration for '+family);
 }
 const views={thermal:['THERMAL / LIGHT','#b9785e','T · L · d'],nutrients:['NITROGEN FORMS','#5a8e80','+ NO₃ · NH₄'],compound:['CO-EXPOSURE','#8c83a0','+ PROM'],interactions:['INTERACTIONS','#b0985b','+ T × chemistry']},v=views[view];
 return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 220"><defs><linearGradient id="paper" x2="0" y2="1"><stop stop-color="#fafbf7"/><stop offset="1" stop-color="#edf2e9"/></linearGradient><pattern id="dots" width="10" height="10" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r=".35" fill="#77917d" opacity=".15"/></pattern></defs><rect width="360" height="220" rx="9" fill="url(#paper)"/><rect width="360" height="220" rx="9" fill="url(#dots)"/><path d="M14 24V14H25M335 14H346V24M14 177V187H25M335 187H346V177" fill="none" stroke="#afbeb0" stroke-width=".7"/>${label(25,26,'MODEL STUDY / '+String(index).padStart(2,'0'),7,'#899d8c')}${art}<path d="M18 193H342" stroke="#cfd9cc" stroke-width=".7"/>${label(24,207,v[0],6.5,v[1])}${label(173,207,v[2],8,v[1])}<text x="326" y="28" fill="#8b9c89" text-anchor="end" font-family="Georgia" font-size="7">${formula}</text></svg>`;
}
